def exists(cid):
    f=urllib.parse.quote(f"{{content_id}}='{cid}'")
    url=f"https://api.airtable.com/v0/{BASE}/{TABLE}?filterByFormula={f}&maxRecords=1"
    req=urllib.request.Request(url,headers=H)
    with urllib.request.urlopen(req) as r: data=json.loads(r.read())
    return len(data.get("records",[]))>0
def create(fields):
    url=f"https://api.airtable.com/v0/{BASE}/{TABLE}"
    body=json.dumps({"records":[{"fields":fields}]}).encode()
    req=urllib.request.Request(url,data=body,headers=H,method="POST")
    with urllib.request.urlopen(req) as r: return json.loads(r.read())
